import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) =>
  ({ id, text, priority, required });

test('validates all field types and budgets even with no available space', () => {
  for (const budget of [-1, 0.5, NaN, Infinity, 2 ** 53, '0', null, undefined]) {
    assert.throws(() => packContext([], budget), Error);
  }
  for (const input of [null, {}, 'x', [null], [[]], [1], [undefined], new Array(2)]) {
    assert.throws(() => packContext(input, 0), Error);
  }
  const badFields = {
    id: ['', null, 1], text: [null, 1],
    priority: [-1, 0.5, Infinity, NaN, 2 ** 53, '0'], required: [0, 1, 'false', null],
  };
  for (const [field, values] of Object.entries(badFields)) {
    for (const value of [...values, undefined]) {
      assert.throws(() => packContext([section('valid'), { ...section('bad'), [field]: value }], 0), Error);
    }
    const missing = section('missing');
    delete missing[field];
    assert.throws(() => packContext([missing], 0), Error);
  }
});

test('preserves unusual IDs and text, exact bytes, and frozen inputs', () => {
  const ids = ['__proto__', 'A', 'a', ' ', '雪\n\u0000"\\', '\ud800'];
  const input = Object.freeze(ids.map(id => Object.freeze(section(id, ' é\r\n🙂 \n'))));
  const text = ids.map(id => '### ' + JSON.stringify(id) + '\n é\r\n🙂 \n\n').join('');
  const bytes = Buffer.byteLength(text, 'utf8');
  assert.deepEqual(packContext(input, bytes), { text, bytes, included: ids, omitted: [] });
  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
});

test('required input order, optional priority ties, and omitted input order', () => {
  const input = [
    section('low', 'x'.repeat(100), 0), section('r1', '', 0, true),
    section('tie1', '', 5), section('high', 'x'.repeat(100), 100),
    section('r2', '', 100, true), section('tie2', '', 5), section('last', '', 1),
  ];
  const expected = ['r1', 'r2', 'tie1', 'tie2'];
  const text = expected.map(id => `### ${JSON.stringify(id)}\n\n`).join('');
  assert.deepEqual(packContext(input, Buffer.byteLength(text)), {
    text, bytes: Buffer.byteLength(text), included: expected, omitted: ['low', 'high', 'last'],
  });
});

test('CLI success, errors, and import without side effects', () => {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
  const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  try {
    const fixture = join(directory, 'input.json');
    const input = { sections: [section('雪', '🙂')], maxBytes: 100, extra: true };
    writeFileSync(fixture, JSON.stringify(input));
    const success = run([fixture]);
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, JSON.stringify(packContext(input.sections, input.maxBytes)) + '\n');
    const fails = [run([]), run([fixture, 'extra']), run([join(directory, 'missing')])];
    for (const contents of ['{', 'null', '[]', '{}', '{"sections":[],"maxBytes":-1}',
      JSON.stringify({ sections: [section('required', '', 0, true)], maxBytes: 0 })]) {
      writeFileSync(fixture, contents);
      fails.push(run([fixture]));
    }
    for (const result of fails) {
      assert.equal(result.status, 2);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.length > 0);
    }
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)}`], { encoding: 'utf8' });
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

